const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Polygon(
    [[[-62.90, -17.80],
      [-62.90, -17.95],
      [-62.75, -17.95],
      [-62.75, -17.80],
      [-62.90, -17.80]]], null, false); // A region east of Santa Cruz de la Sierra

  const date1986_start = '1986-08-01';
  const date1986_end = '1986-08-31';
  const date2001_start = '2001-08-01';
  const date2001_end = '2001-08-31';

  const LANDSAT_SCALE = 30; // Landsat resolution in meters
  const REDUCER_SCALE = 1000; // Scale for reduceRegion to avoid memory issues

  // Function to mask clouds and shadows from Landsat 5 SR data.
  // Using pixel_qa band for cloud and shadow masking.
  function maskL5SR(image) {
    const qa = image.select('pixel_qa');
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
      .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    return image.updateMask(mask).divide(10000) // Scale to 0-1 range
      .select(['B3', 'B4']) // Select red and nir bands
      .copyProperties(image, ['system:time_start']);
  }

  // Function to calculate NDVI.
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B4', 'B3']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // 2. Data Acquisition & Check
  let collection1986 = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
    .filterDate(date1986_start, date1986_end)
    .filterBounds(aoi)
    .map(maskL5SR)
    .map(addNDVI);

  let collection2001 = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
    .filterDate(date2001_start, date2001_end)
    .filterBounds(aoi)
    .map(maskL5SR)
    .map(addNDVI);

  const size1986 = await collection1986.size().getInfo();
  const size2001 = await collection2001.size().getInfo();

  if (size1986 === 0 || size2001 === 0) {
    console.log(`1986 Images: ${size1986}`);
    console.log(`2001 Images: ${size2001}`);
    console.log("C1: Empty Collection (No images found for one or both periods after initial filtering).");
    return;
  }

  // Take the median composite to get a single image for each period.
  const image1986 = collection1986.median();
  const image2001 = collection2001.median();

  // 3. Processing (Calculate pixel count to detect C2)
  // Check valid pixels after masking and compositing
  const pixelCount1986 = await image1986.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: REDUCER_SCALE,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const pixelCount2001 = await image2001.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: REDUCER_SCALE,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`1986 Images: ${size1986}, Pixels (1986): ${pixelCount1986}`);
  console.log(`2001 Images: ${size2001}, Pixels (2001): ${pixelCount2001}`);

  if (pixelCount1986 === 0 || pixelCount2001 === 0 || pixelCount1986 === null || pixelCount2001 === null) {
    console.log("C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).");
    return;
  }

  // 4. Calculation - Forest Cover
  // Define a simple forest threshold for NDVI (e.g., NDVI > 0.3 for forest)
  const FOREST_THRESHOLD = 0.3;

  // Calculate forest mask: 1 where NDVI > threshold, 0 otherwise
  const forestMask1986 = image1986.select('NDVI').gt(FOREST_THRESHOLD).selfMask();
  const forestMask2001 = image2001.select('NDVI').gt(FOREST_THRESHOLD).selfMask();

  // Calculate forest area in square meters
  const forestArea1986 = forestMask1986.multiply(ee.Image.pixelArea());
  const forestArea2001 = forestMask2001.multiply(ee.Image.pixelArea());

  // Reduce the area to get total forest area in square kilometers
  const stats1986 = await forestArea1986.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: REDUCER_SCALE,
    maxPixels: 1e9
  }).getInfo();

  const stats2001 = await forestArea2001.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: REDUCER_SCALE,
    maxPixels: 1e9
  }).getInfo();

  const totalForestArea1986_sqm = stats1986['sum'] || 0;
  const totalForestArea2001_sqm = stats2001['sum'] || 0;

  // 5. Validation & Final Answer
  if (totalForestArea1986_sqm === null || totalForestArea2001_sqm === null ||
      isNaN(totalForestArea1986_sqm) || isNaN(totalForestArea2001_sqm)) {
    console.log("C3: Calculation Failure (Result is None, NaN, or invalid).");
    return;
  }

  const totalForestArea1986_ha = totalForestArea1986_sqm / 10000; // Convert sq meters to hectares
  const totalForestArea2001_ha = totalForestArea2001_sqm / 10000;

  console.log(`Forest Area 1986: ${totalForestArea1986_ha.toFixed(2)} ha`);
  console.log(`Forest Area 2001: ${totalForestArea2001_ha.toFixed(2)} ha`);

  if (totalForestArea2001_ha < totalForestArea1986_ha) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
